	msg := req.Msg
	log.Printf("Creating new food %v with %v calories", msg.Name, msg.Calories)
	row, err := s.q.CreateFood(ctx, db.CreateFoodParams{
		Name:       msg.Name,
		Calories:   floatToNumeric(msg.Calories),
		ProteinG:   floatToNumeric(msg.ProteinG),
