    );

  const empty =
    document.getElementById(
      "d-empty"
    );


  body.innerHTML = "";


  if (entries.length === 0) {

    table.style.display = "none";

    empty.style.display = "block";

    return;
  }


  table.style.display = "table";

  empty.style.display = "none";


  /* Map food IDs to foods */

  const byId =
    Object.fromEntries(
      foods.map((f) => [
        f.id,
        f
      ])
    );


