      proteinCell.textContent =
        Math.round(
          f.proteinG * mult
        );


      const carbsCell =
        document.createElement("td");

      carbsCell.textContent =
        Math.round(
          f.carbsG * mult
        );


      const fatCell =
        document.createElement("td");

      fatCell.textContent =
        Math.round(
          f.fatG * mult
        );


      tr.appendChild(foodCell);
      tr.appendChild(multCell);
      tr.appendChild(calCell);
      tr.appendChild(proteinCell);
      tr.appendChild(carbsCell);
      tr.appendChild(fatCell);
    }


