	logAddCmd.MarkFlagRequired("food-id")

	logTodayCmd.Flags().StringVar(&todayDate, "date", "", "date (YYYY-MM-DD), defaults to today")

	logCmd.AddCommand(logAddCmd, logRmCmd, logLsCmd, logTodayCmd)
}

